// HTTPS availability canary: calls TARGET_URL on 443 expecting HTTP 200. Uses
// executeHttpStep (not a full browser) so a DNS failure, TLS failure, timeout, or non-200
// status each surface as a distinct, readable failure reason in the canary run's logs --
// that's how an operator tells which layer broke, per the monitoring spec.

const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

const checkHttpsAvailability = async function () {
    const targetUrl = new URL(process.env.TARGET_URL);

    const requestOptions = {
        hostname: targetUrl.hostname,
        method: 'GET',
        path: targetUrl.pathname || '/',
        port: 443,
        protocol: 'https:',
        headers: { 'User-Agent': synthetics.getCanaryUserAgentString() },
    };

    const stepConfig = {
        includeRequestHeaders: true,
        includeResponseHeaders: true,
        includeRequestBody: false,
        includeResponseBody: false,
        continueOnHttpStepFailure: false,
    };

    await synthetics.executeHttpStep('verifyHttps200', requestOptions, async (res) => {
        return new Promise((resolve, reject) => {
            if (res.statusCode !== 200) {
                reject(new Error(`Expected HTTP 200 from ${targetUrl}, got ${res.statusCode} ${res.statusMessage}`));
                return;
            }
            log.info(`${targetUrl} returned HTTP 200`);
            resolve();
        });
    }, stepConfig);
};

exports.handler = async () => {
    return await checkHttpsAvailability();
};
